-- Run in Supabase SQL Editor as project owner. Add admin users manually as described in README.
create extension if not exists pgcrypto;
create table if not exists public.admins(user_id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table if not exists public.articles(id uuid primary key default gen_random_uuid(),title text not null check(char_length(title) between 1 and 180),slug text not null unique check(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),summary text not null check(char_length(summary) between 1 and 350),body text not null,category text not null default 'News',author text not null default 'DGC TV Editorial Desk',image_url text,image_alt text,status text not null default 'draft' check(status in ('draft','published')),published_at timestamptz,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists articles_published_idx on public.articles(published_at desc) where status='published';
create index if not exists articles_category_idx on public.articles(category);
alter table public.admins enable row level security; alter table public.articles enable row level security;
drop policy if exists "admin reads own allowlist row" on public.admins; create policy "admin reads own allowlist row" on public.admins for select to authenticated using(user_id=(select auth.uid()));
drop policy if exists "public reads published articles" on public.articles; create policy "public reads published articles" on public.articles for select to anon,authenticated using(status='published' and published_at is not null and published_at<=now());
drop policy if exists "admins read all articles" on public.articles; create policy "admins read all articles" on public.articles for select to authenticated using(exists(select 1 from public.admins a where a.user_id=(select auth.uid())));
drop policy if exists "admins insert articles" on public.articles; create policy "admins insert articles" on public.articles for insert to authenticated with check(exists(select 1 from public.admins a where a.user_id=(select auth.uid())) and created_by=(select auth.uid()));
drop policy if exists "admins update articles" on public.articles; create policy "admins update articles" on public.articles for update to authenticated using(exists(select 1 from public.admins a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.admins a where a.user_id=(select auth.uid())));
drop policy if exists "admins delete articles" on public.articles; create policy "admins delete articles" on public.articles for delete to authenticated using(exists(select 1 from public.admins a where a.user_id=(select auth.uid())));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('article-images','article-images',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=true,file_size_limit=5242880,allowed_mime_types=array['image/jpeg','image/png','image/webp'];
drop policy if exists "public views article images" on storage.objects; create policy "public views article images" on storage.objects for select to anon,authenticated using(bucket_id='article-images');
drop policy if exists "admins upload own article images" on storage.objects; create policy "admins upload own article images" on storage.objects for insert to authenticated with check(bucket_id='article-images' and (storage.foldername(name))[1]=(select auth.uid())::text and exists(select 1 from public.admins a where a.user_id=(select auth.uid())));
drop policy if exists "admins update own article images" on storage.objects; create policy "admins update own article images" on storage.objects for update to authenticated using(bucket_id='article-images' and (storage.foldername(name))[1]=(select auth.uid())::text and exists(select 1 from public.admins a where a.user_id=(select auth.uid()))) with check(bucket_id='article-images' and (storage.foldername(name))[1]=(select auth.uid())::text and exists(select 1 from public.admins a where a.user_id=(select auth.uid())));
drop policy if exists "admins delete own article images" on storage.objects; create policy "admins delete own article images" on storage.objects for delete to authenticated using(bucket_id='article-images' and (storage.foldername(name))[1]=(select auth.uid())::text and exists(select 1 from public.admins a where a.user_id=(select auth.uid())));
